  TemplateTable,
  type TemplateTableKind,
} from "./template-table";

export interface DashboardTemplateProps {
  contained?: boolean;
  className?: string;
  rows?: TemplateRow[];
  onRowsChange?: (rows: TemplateRow[]) => void;
}

export function DataDashboard({
  kind,
  title,
  selected,
  action,
  children,
  contained,
  className,
  rows: supplied,
  onRowsChange,
}: DashboardTemplateProps & {
  kind: TemplateTableKind;
  title: string;
  selected: string;
  action: string;
  children: ReactNode;
}) {
  const [localRows, setLocalRows] = useState(() => createTemplateRows(kind));
  const [adding, setAdding] = useState(false);
  const rows = supplied ?? localRows;
  const update = (next: TemplateRow[]) => {
    setLocalRows(next);
    onRowsChange?.(next);
  };
  return (
    <TemplateShell
      title={title}
      selected={selected}
      action={action}
      onAction={() => setAdding(true)}
      contained={contained}
      className={className}
    >
      {children}
      <TemplateTable kind={kind} rows={rows} onRowsChange={update} />
      {adding && (
        <TemplateRecordDialog
          kind={kind}
          row={{
            id: "new",
            name: "",
            category: "",
            date: new Date().toISOString().slice(0, 10),
            status: kind === "finance" ? "Checking" : kind === "medical" ? "Outpatient" : "Active",
            amount: 0,
          }}
          onClose={() => setAdding(false)}
          onSave={(row) => {
            update([{ ...row, id: globalThis.crypto.randomUUID() }, ...rows]);
            setAdding(false);
          }}
        />
      )}
    </TemplateShell>
  );
}

